import java.util.*;

class Solution {
    public void moveZeroes(int[] nums) {
        int k = 0; // next slot for a non-zero value
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] != 0) {
                int t = nums[i];
                nums[i] = nums[k];
                nums[k] = t;
                k++;
            }
        }
    }
}

